        \"name\": \"Qwen3-14B (non-thinking)\",
        \"format\": \"results_list\",
    },
}
'''
# Find start (SC_SOURCES = {) and end of the block
start = None
end = None
brace_count = 0
for i, line in enumerate(lines):
    if 'SC_SOURCES = {' in line:
        start = i
        brace_count = 1
        continue
    if start is not None:
        brace_count += line.count('{') - line.count('}')
        if brace_count <= 0:
            end = i
            break
lines[start:end+1] = [new_block]
open('scripts/eval_finetuned_nli.py', 'w').writelines(lines)
print('Done')
